def _init_weights(self, module: nn.Module) -> None:
    """Initialize weights per §15.1 of the architecture doc.

    Residual-stream-writing projections (attention `o_proj`, FFN
    `down_proj`) are marked `_is_residual_writer = True` in their parent
    modules; when `config.init_scale_output_projections` is set, their std
    is shrunk by `1/sqrt(2 * num_hidden_layers)` to keep the residual
    stream variance stable with depth.

    Under μP (`config.mup_enable`), hidden weight matrices additionally
    shrink their std by `1/sqrt(m_W)`, where `m_W` is the per-matrix fan-in
    multiplier `fan_in / fan_in_base` (`OplmConfig.mup_fanin_mult`). μP
    readouts (`lm_head.decoder`, the `classifier` heads; tagged
    `_is_readout = True`) keep a width-independent std `σ` and never receive
    the `1/sqrt(m_W)` factor; embeddings (μP input weights) likewise stay at
    `σ`. Every μP factor is a no-op (`m_W = 1`) at the base width or when μP
    is disabled, so init is bit-for-bit identical to the non-μP path there.
    """
    std = self.config.initializer_range

    if isinstance(module, nn.Linear):
        if getattr(module, "_is_readout", False):
            # μP readout: width-independent init, no 1/sqrt(m_W) factor.
            module_std = std
        else:
            module_std = std / math.sqrt(self.config.mup_fanin_mult(module.in_features))
            if getattr(module, "_is_residual_writer", False) and (
                self.config.init_scale_output_projections
            ):
                module_std /= math.sqrt(2 * self.config.num_hidden_layers)
        nn.init.trunc_normal_(
            module.weight, mean=0.0, std=module_std, a=-2 * module_std, b=2 * module_std
        )
        if module.bias is not None:
            nn.init.zeros_(module.bias)
    elif isinstance(module, nn.Embedding):
        nn.init.trunc_normal_(module.weight, mean=0.0, std=std, a=-2 * std, b=2 * std)
        # HF convention: do NOT zero the <pad> row.
    elif isinstance(module, nn.Conv1d):
        nn.init.trunc_normal_(module.weight, mean=0.0, std=std, a=-2 * std, b=2 * std)
        if module.bias is not None:
            nn.init.zeros_(module.bias)
    elif isinstance(module, (OplmLayerNorm, OplmRMSNorm)):
        if getattr(module, "weight", None) is not None:
            nn.init.ones_(module.weight)

"""Trainer callback interface for stable training-event observation."""

from __future__ import annotations

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from pathlib import Path

    from oplm.training.trainer import Trainer


class TrainerCallback:
    """Minimal main-process callback surface exposed by :class:`Trainer`."""

    def on_train_start(self, trainer: Trainer) -> None:
        """Called once before the training loop begins."""

    def on_log(self, trainer: Trainer, metrics: dict[str, float], step: int) -> None:
        """Called whenever the trainer logs metrics through ``accelerator.log``."""

    def on_eval_end(self, trainer: Trainer, metrics: dict[str, float], step: int) -> None:
        """Called after an evaluation pass emits its aggregated metrics."""

    def on_checkpoint_saved(self, trainer: Trainer, checkpoint_dir: Path, step: int) -> None:
        """Called after a checkpoint directory has been written."""

    def on_train_end(self, trainer: Trainer) -> None:
        """Called once when the training loop finishes or exits early."""

# train/base.yaml carries OPLM's opinionated production defaults (μP + Muon), which
# intentionally diverge from the conservative TrainConfig dataclass fallbacks for
# these fields. Every other key must still mirror the dataclass (drift guard).
_TRAIN_PRODUCTION_OVERRIDES = {"optimizer", "lr", "muon_adjust_lr_fn"}


@pytest.mark.parametrize("key", sorted(_TRAIN_YAML))
def test_train_base_yaml_matches_dataclass(key: str) -> None:
    """Every ``train/base.yaml`` key is a ``TrainConfig`` field; non-overrides equal the default."""
    defaults = asdict(TrainConfig())
    assert key in defaults, f"{key!r} is not a TrainConfig field"
    if key not in _TRAIN_PRODUCTION_OVERRIDES:
        assert _TRAIN_YAML[key] == defaults[key]


@pytest.mark.parametrize("key", sorted(_DATA_YAML))
def test_data_base_yaml_matches_dataclass(key: str) -> None:
    """Every ``data/base.yaml`` key equals its ``DataConfig`` default (train/eval are None)."""
    defaults = asdict(DataConfig())
    assert key in defaults, f"{key!r} is not a DataConfig field"
    assert _DATA_YAML[key] == defaults[key]


